<##
.SYNOPSIS
  Builds a non-executing scope-first hybrid retrieval plan for one Memory Cube.
##>
param([Parameter(Mandatory=$true)][string]$GrantPath,[Parameter(Mandatory=$true)][string]$CubeId,[Parameter(Mandatory=$true)][string]$TenantId,[Parameter(Mandatory=$true)][string]$OrganizationId,[Parameter(Mandatory=$true)][string]$ProjectId,[Parameter(Mandatory=$true)][string]$RoleId,[Parameter(Mandatory=$true)][string]$MemoryLayers,[Parameter(Mandatory=$true)][string]$QueryText,[ValidateRange(1,20)][int]$MaxItems=5,[switch]$PassThru)
$ErrorActionPreference='Stop';$projectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$grantRoot=[IO.Path]::GetFullPath((Join-Path $projectRoot '.qianlima/run-traces/delegation-grants')).TrimEnd('\','/')+[IO.Path]::DirectorySeparatorChar;$revocationPath=Join-Path $projectRoot '.qianlima/run-traces/grant-revocations.jsonl';function Emit([hashtable]$Value,[int]$Code=0){if($PassThru){$Value|ConvertTo-Json -Depth 12}else{$Value|Format-List};if($Code-ne0){exit $Code}}
try{$full=(Resolve-Path -LiteralPath $GrantPath -ErrorAction Stop).Path;$grant=Get-Content -LiteralPath $full -Raw -Encoding UTF8|ConvertFrom-Json}catch{Emit ([ordered]@{status='blocked';reason='grant_not_found_or_invalid';retrieval_executed=$false}) 1};if(-not$full.StartsWith($grantRoot,[StringComparison]::OrdinalIgnoreCase)){Emit ([ordered]@{status='blocked';reason='grant_outside_governed_root';retrieval_executed=$false}) 1};$layerList=@($MemoryLayers-split';'|Where-Object{$_});if(@($layerList|Where-Object{$_-notin@('trajectory','strategy','world_model','skill')}).Count-or-not$layerList.Count){Emit ([ordered]@{status='blocked';reason='invalid_memory_layers';retrieval_executed=$false}) 1};$violations=[System.Collections.Generic.List[string]]::new();function Deny([string]$Id){[void]$violations.Add($Id)};if([string]$grant.status-ne'issued'){Deny 'grant_not_issued'};try{if([DateTime]::Parse([string]$grant.expires_at).ToUniversalTime()-le[DateTime]::UtcNow){Deny 'grant_expired'}}catch{Deny 'grant_expiry_invalid'};if([string]$grant.tenant_id-ne$TenantId){Deny 'tenant_mismatch'};if([string]$grant.organization_id-ne$OrganizationId){Deny 'organization_mismatch'};if([string]$grant.project_id-ne$ProjectId){Deny 'project_mismatch'};if([string]$grant.role_id-ne$RoleId){Deny 'role_mismatch'};if(@($grant.data_refs)-notcontains('memory-cube://'+$CubeId)){Deny 'cube_outside_grant'};if(@($grant.allowed_tools)-notcontains'query_memory'){Deny 'query_memory_not_granted'};if(Test-Path -LiteralPath $revocationPath){foreach($line in @(Get-Content -LiteralPath $revocationPath -Encoding UTF8)){if($line){try{$r=$line|ConvertFrom-Json;if([string]$r.grant_id-eq[string]$grant.grant_id){Deny 'grant_revoked';break}}catch{Deny 'revocation_ledger_invalid';break}}}};if($violations.Count){Emit ([ordered]@{status='blocked';violations=@($violations);retrieval_executed=$false;external_calls=$false}) 1}
$sha=[Security.Cryptography.SHA256]::Create();try{$queryHash=([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($QueryText)))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()};$plan=[ordered]@{schema_version=1;status='planned';query_hash='sha256:'+$queryHash;query_text_stored=$false;cube=[ordered]@{cube_id=$CubeId;tenant_id=$TenantId;organization_id=$OrganizationId;project_id=$ProjectId;role_id=$RoleId};memory_layers=$layerList;classification_allowlist=@($grant.allowed_data_classifications);max_items=$MaxItems;mandatory_stages=@('task_and_grant_gate','cube_scope_filter','classification_filter','state_expiry_revocation_filter','deduplicate','fts5_recall','vector_recall','temporal_recall','rerank','minimum_pack','audit');fusion='weighted_reciprocal_rank_with_policy_filters';scope_filter_precedes_similarity=$true;retrieval_executed=$false;listener_opened=$false;external_calls=$false;business_write=$false};Emit $plan
